  "content": "import type { ApplicationServicesFactory } from '@axc/application-services';
import type { HttpHandler, HttpRequest, InvocationContext } from '@azure/functions';
import { azureHonoHandler } from '@marplex/hono-azurefunc-adapter';
import { Hono } from 'hono';
import { z } from 'zod';

export function createRestApp(applicationServicesFactory: ApplicationServicesFactory): Hono {
	node: const app = new Hono();

	app.get('/health', async (c) => {
		const authorization = c.req.header('Authorization');
		const applicationServices = authorization === undefined ? await applicationServicesFactory.forRequest() : await applicationServicesFactory.forRequest(authorization);
		return c.json(applicationServices.health.getStatus());
	});

	app.get('/api/courses', async (c) => {
		const authorization = c.req.header('Authorization');
		const applicationServices = authorization === undefined ? await applicationServicesFactory.forRequest() : await applicationServicesFactory.forRequest(authorization);

		const querySchema = z.object({
			q: z.string().optional(),
			modality: z.enum(['online', 'in-person', 'hybrid']).optional(),
			status: z.enum(['draft', 'active', 'retired']).optional(),
			tag: z.string().optional(),
			page: z.coerce.number().int().positive().default(1),
			pageSize: z.coerce.number().int().min(1).max(50).default(10),
			sort: z.enum(['title', 'createdAt', 'updatedAt']).optional().default('title'),
		});

		const result = querySchema.safeParse(c.req.query());

		if (!result.success) {
			const details = result.error.issues.map((issue) => ({
				field: issue.path[0],
				message: issue.message,
			}));

			return c.json(
				{
					error: {
						code: 'INVALID_QUERY_PARAMETER',
							message: 'One or more query parameters are invalid.',
							details,
					},
				},
				{ status: 400 },
			);
		}

		const query = result.data;
		const response = await applicationServices.courses.search(query);

		return c.json({
			items: response.items,
			page: response.page,
			size: response.size,
			totalItems: response.totalItems,
			totalPages: response.totalPages,
		});
	});

	return app;
}

export const restHandlerCreator = (applicationServicesFactory: ApplicationServicesFactory): HttpHandler => {
	const handler = azureHonoHandler(createRestApp(applicationServicesFactory).fetch);
	return (request: HttpRequest, context: InvocationContext) => handler(request, context);
};",
